
.bounce-enter-active {
  animation: bounce-in 0.5s;
}
.bounce-leave-active {
  animation: bounce-in 0.5s reverse;
}
@keyframes bounce-in {
  0% {
    transform: scale(0);
  }
  50% {
    transform: scale(1.25);
  }
  100% {
    transform: scale(1);
  }
}

/* 搜索栏样式 */
.search-bar {
  display: flex;
  margin: 1rem 0 0.5rem 0;
  input {
    background: rgba(0, 0, 0, 0.5);
    border: 1px solid #484a4c;
    color: aliceblue;
    padding: 0.4rem 0.8rem;
    border-radius: 4px;
    outline: none;
    flex: 1;
    font-size: 0.85rem;
    max-width: 100%;
  }
  input:focus {
    border-color: mediumslateblue;
  }
}
/* 标签容器和按钮样式 */
.tags-root {
  display: flex;
  gap: 5px;
  margin-bottom: 1rem;
  > div:nth-child(1) {
    display: flex;
    flex: 1;
    min-width: 0;
    flex-wrap: wrap;
    gap: 0.5rem;
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
    padding-bottom: 2px;

    @media screen and (max-width: 600px) {
      display: grid;
      /* 核心 1：固定为 2 行（如果想展示 3 行就写 3 个 max-content 或 repeat(3, auto)） */
      grid-template-rows: repeat(2, auto);
      /* 核心 2：让元素按“列”自动向右延展，而不是按行换行 */
      grid-auto-flow: column;
      /* 核心 3：每列宽度自适应内容 */
      grid-auto-columns: max-content;
      flex: 1;
      min-width: 0; /* 允许容器宽度收缩，从而触发横向滚动 */
      gap: 0.5rem;
      overflow-x: auto; /* 开启横向滚动 */
      -webkit-overflow-scrolling: touch;
      padding-bottom: 4px; /* 留一点边距防滚动条挤压/边框切边 */
    }
  }

  .tag-item {
    display: flex;
    flex-shrink: 0;
    background: rgba(0, 0, 0, 0.3);
    border: 1px solid #484a4c;
    color: #aaa;
    border-radius: 4px;
    font-size: 0.8rem;
    transition: all 0.2s ease;
    overflow: hidden; /* 防止内部悬停超出边框圆角 */
    &.is-included {
      background: rgba(46, 139, 87, 0.3); /* 海绿色 */
      border-color: #2e8b57;
      color: #98fb98;
      .tag-exclude-btn {
        border-left-color: #2e8b57;
      }
    }
    &.is-excluded {
      background: rgba(178, 34, 34, 0.3); /* 耐火砖红 */
      border-color: #b22222;
      color: #ffb6c1;
      .tag-exclude-btn {
        border-left-color: #b22222;
      }
    }
    /* 标签主体（点击包含） */
    .tag-main {
      display: flex;
      flex: 1;
      align-items: center;
      gap: 0.3rem;
      padding: 0.3rem 0.5rem 0.3rem 0.6rem;
      cursor: pointer;
      transition: all 0.2s ease;
      &:hover {
        background: rgba(255, 255, 255, 0.1);
        color: aliceblue;
      }
    }
    /* 标签排除按钮（点击排除） */
    .tag-exclude-btn {
      font-size: 0.5rem;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 0.3rem 0.5rem;
      border-left: 1px solid #484a4c;
      cursor: pointer;
      transition: all 0.2s ease;
      opacity: 0.8;
      &:hover {
        background: rgba(178, 34, 34, 0.6);
        color: white;
        opacity: 1;
      }
    }
  }
  .fav-filter-btn {
    flex-shrink: 0;
    flex-basis: 2rem;
    align-self: flex-end;
    display: flex;
    align-items: center;
    justify-items: center;
    justify-content: center;
    aspect-ratio: 1 / 1;
    &.is-active {
      background: color-mix(in srgb, var(--oz-highlight) 20%, transparent 80%) !important;
      border-color: var(--oz-highlight) !important;
      color: var(--oz-highlight) !important;
    }
  }
}

.tag-list {
  margin-left: 0.5rem;
  font-size: 0.85rem;
  color: #888;
}

li.empty-moon {
  color: #888;
  font-style: italic;
  cursor: not-allowed;

  display: flex;
  .fa-regular {
    align-self: baseline;
  }
}
section {
  background: rgba(255, 255, 255, 0.05);
  border-radius: inherit;
  box-shadow:
    0 0 0 1px #484a4c,
    0 1px 3px 0 rgb(0 0 0 / 0.1),
    0 1px 2px -1px rgb(0 0 0 / 0.1);
  margin: 1rem 0;
  padding-top: 1rem;
  padding-bottom: 1rem;

  ul {
    height: 20rem;
    overflow-x: auto;

    scrollbar-gutter: stable;

    // padding-left: 0.5rem;

    // @media screen and (max-width: 600px) {
    //   padding-left: 0;
    // }
    li.is-favorite {
      background: color-mix(in srgb, var(--oz-highlight) 10%, transparent 90%);
      > i:first-of-type {
        color: color-mix(in srgb, var(--oz-highlight) 70%, transparent 30%);
      }
      > div:first-of-type > span:first-of-type {
        border: 1px solid color-mix(in srgb, var(--oz-highlight) 60%, black 30%);
      }
    }
    // @media screen and (min-width: 600px) {
    //   > li.is-favorite:nth-child(odd) {
    //     background: rgba(186, 156, 246, 0.16);
    //   }
    // }
    li {
      // display: flex;
      // justify-content: flex-start;
      // align-items: baseline;
      gap: 4px;
      cursor: pointer;

      user-select: none;
      -moz-user-select: none;
      -khtml-user-select: none;
      -webkit-user-select: none;
      -o-user-select: none;

      transition: 0.3s;

      display: flex;
      align-items: center;

      > i:first-of-type {
        margin-right: 0.5rem;
        color: #ffffff44;
        font-size: 0.95rem;
        cursor: pointer;
        transition: all 0.2s ease;
        margin-left: auto;
        &:hover {
          color: var(--oz-highlight);
          transform: scale(1.2);
        }
      }

      > div:first-of-type {
        flex-grow: 2;
        padding: 0.5rem 0;

        padding-left: 0.5rem;
        > i:first-of-type {
          width: 1.2rem;
          height: 1.2rem;
          display: inline-block;
          padding-top: 4px;
        }

        > span:first-of-type {
          background: black;
          font-family: 'Consolas', 'Menlo', 'Monaco', 'DejaVu Sans Mono', 'Ubuntu Mono', 'Courier New', monospace;
          display: inline-block;
          border: 1px solid #484a4c;
          width: 1.2rem;
          height: 1.2rem;
          line-height: 1.2rem;
          font-size: 0.8rem;
          text-align: center;
          border-radius: 4px;
          transition: 0.3s;
        }
      }

      @media screen and (max-width: 600px) {
        > div:first-of-type {
          padding-left: 0;
        }
        border-bottom: 1px solid #ffffff3d;
      }
      // .favorite {
      //   float: right;
      // }
    }
    > :not(li:first-of-type):not(.empty-moon):hover,
    > :not(li:first-of-type):not(.empty-moon):active {
      //color: mediumpurple;
      background: rgba(255, 255, 255, 0.15);
      > div:first-of-type > span:first-of-type {
        color: black;
        background-color: white;
      }
      &.is-favorite {
        background: color-mix(in srgb, var(--oz-highlight) 30%, transparent 70%);
      }
    }
    @media screen and (min-width: 600px) {
      > :nth-child(odd) {
        background: rgba(255, 255, 255, 0.05);
      }
    }
    > li:first-of-type {
      cursor: not-allowed;
    }
  }

  ::-webkit-scrollbar {
    width: 6px;
    @media screen and (max-width: 600px) {
      width: 4px;
    }
    height: 6px; /* 横向滚动条高度变细 */
    @media screen and (max-width: 600px) {
      height: 4px;
    }
  }

  ::-webkit-scrollbar-track {
    border-radius: 8px;
    background-color: rgba(0, 0, 0, 0.3);
    border: 1px solid #666;
  }

  ::-webkit-scrollbar-thumb {
    border-radius: 8px;
    background-color: #666;
  }
}
